6.2.1    Claim rewards for all delegators function checks are insufficient
     File(s): src/validator_registry/validator_registry.cairo
     Description: The _claim_rewards_for_all_delegators(...) function is used to claim all the rewards for delegators. Simply, it calls the
     claim_rewards(...) function on delegator contracts. However, the loop does not check whether the delegator is still active.

 1   // ...
 2   fn _claim_rewards_for_all_delegators(
 3       ref self: ContractState, validator: ContractAddress, token: ContractAddress,
 4   ) -> u128 {
 5       // ...
 6       while i != delegator_count {
 7           let delegator = self.delegator_mapping.read((validator, token, i));
 8           assert(delegator.is_non_zero(), Errors::DELEGATOR_NOT_FOUND);
 9           let disp = IDelegatorDispatcher { contract_address: delegator };
10           total_claim_amount += disp.claim_rewards(token);
11           i += 1;
12       }
13   }

     Recommendation(s): Consider refactoring delegator mappings and checking that the delegator is active before calling the claim_rewards
     function.
     Status: Fixed
     Update from the client: Fixed in fba3231

6.2.3    Contracts can be re-initialized
     File(s): src/delegator/delegator.cairo, src/lst/lst.cairo
     Description: LST and Delegator contracts have an initializer(...) function which can be called by default admin only. It executes
     critical operations like infinite approval. These have to be done only once. However, these functions can be called by the admin anytime.

 1   fn initializer(ref self: ContractState, calldata: Array<felt252>) {
 2       // @audit-issue Can be reinitialized by admin
 3       // ** Do not touch this block
 4       self.common.assert_default_admin_only();
 5       // ----------------------------------
 6
 7        // update below lines if required for upgrade
 8        let asset = self.erc4626.asset();
 9        let validator_regitry = self.config.read().validator_registry.contract_address;
10        erc20helper::approve(asset, validator_regitry, Bounded::<u256>::MAX);
11

12        // update karnot validator stake in VR
13        let karnot: ContractAddress =
14            0x072543946080646d1aac08bb4ba6f6531b2b29ce41ebfe72b8a6506500d5220e
15            .try_into()
16            .unwrap();
17        let val_disp = self._get_validator_dispatcher();
18        let stake_token = self.erc4626.asset();
19        val_disp
20            .set_validator_stake(
21                 karnot, stake_token, self.staked_amount.read().try_into().unwrap(),
22            );
23
24        // transfer assets to VR
25        let balance = erc20helper::balanceOf(asset, get_contract_address());
26        val_disp.receive_funds(karnot, asset, balance.try_into().unwrap());
27   }

 1   fn initializer(ref self: ContractState, calldata: Array<felt252>) {
 2       //
 3       // ** Do not touch this block
 4       self.common.assert_default_admin_only();
 5       // ----------------------------------
 6
 7        // update below lines if required for upgrade
 8        let mut data = calldata.span();
 9        let tokens: Array<ContractAddress> = Serde::<
10            Array<ContractAddress>,
11        >::deserialize(ref serialized: data)
12            .expect('Failed deserialization');
13        for token in tokens {
14            self._give_infinite_approval(token);
